cr AS (
    SELECT mint, min(evt_block_time) AS curve_created_at, min_by(symbol, evt_block_time) AS c_symbol,
           min_by(name, evt_block_time) AS c_name, count(*) AS n_create
    FROM pumpdotfun_solana.pump_evt_createevent
    WHERE evt_block_date BETWEEN DATE '2024-01-01' AND DATE '2025-04-30'
      AND mint IN (SELECT mint FROM m)
    GROUP BY 1
),
cm AS (
    SELECT mint, min(evt_block_time) AS completed_at, count(*) AS n_complete
    FROM pumpdotfun_solana.pump_evt_completeevent
    WHERE evt_block_date BETWEEN DATE '2025-03-01' AND DATE '2025-04-30'
      AND mint IN (SELECT mint FROM m)
    GROUP BY 1
),
pl AS (
    SELECT base_mint AS mint, min(evt_block_time) AS pool_created_at, min_by(pool, evt_block_time) AS pool, count(*) AS n_pool
    FROM pumpdotfun_solana.pump_amm_evt_createpoolevent
    WHERE evt_block_date BETWEEN DATE '2025-03-15' AND DATE '2025-04-30'
      AND evt_outer_executing_account = '6EF8rrecthR5Dkzon8Nwu78hRvfCKubJ14M5uBEwF6P'
      AND index = 0
      AND base_mint IN (SELECT mint FROM m)
    GROUP BY 1
)
SELECT m.mint, to_unixtime(cr.curve_created_at) AS curve_created_t, cr.c_symbol, cr.c_name, cr.n_create,
       to_unixtime(cm.completed_at) AS completed_t, cm.n_complete,
       to_unixtime(pl.pool_created_at) AS pool_created_t, pl.pool, pl.n_pool
FROM m
LEFT JOIN cr ON cr.mint = m.mint
LEFT JOIN cm ON cm.mint = m.mint
LEFT JOIN pl ON pl.mint = m.mint
